#!/usr/bin/env python3
import json
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CODE_ROOTS = ["Assets/Scripts", "Assets/Tests"]
SKIP_FILES = {
    "Assets/Scripts/Core/NewInputSystem/GameInput.cs": "generated by the Input System",
    "Assets/Scripts/ObjectSystem/Map/Tools/FastNoiseLite.cs": "vendored",
}
LARGE_LIMIT = 500
INDEX_PATH = "docs/map/INDEX.md"
LARGE_PATH = "docs/map/LARGE_FILES.md"
CHECKED_DOCS = ["README.md", "CLAUDE.md", "AGENTS.md", "docs/PROMPT_TEMPLATE.md"]
CHECKED_DIRS = ["docs/map"]
SCRIPT_RELATIVE_DOCS = ["docs/OPTIMIZATION.md", "docs/SECURITY.md"]
PATH_EXT = (".cs", ".md", ".hlsl", ".shader", ".compute", ".asmdef", ".asset", ".prefab", ".unity", ".py", ".yml", ".json", ".inputactions")

TYPE_RX = re.compile(r"\b(class|struct|interface|enum|record)\s+([A-Za-z_]\w*)")
NAMESPACE_RX = re.compile(r"\bnamespace\s+([A-Za-z_][\w.]*)")
ATTR_RX = re.compile(r"^\s*(\[[^\]]*\]\s*)+")
METHOD_RX = re.compile(r"([A-Za-z_]\w*)\s*(<[^>()]*>)?\s*\($")
NOT_METHODS = {"if", "for", "foreach", "while", "switch", "using", "lock", "return", "new", "catch", "fixed", "nameof", "typeof", "sizeof", "default", "when", "base", "this"}


def rel(path):
    return os.path.relpath(path, ROOT).replace(os.sep, "/")


def read(path):
    with open(os.path.join(ROOT, path), encoding="utf-8-sig", errors="replace") as f:
        return f.read()


def cs_files():
    out = []
    for base in CODE_ROOTS:
        for d, _, files in os.walk(os.path.join(ROOT, base)):
            for f in files:
                if f.endswith(".cs"):
                    out.append(rel(os.path.join(d, f)))
    return sorted(out)


def blank_noise(text):
    out = []
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        two = text[i:i + 2]
        if two == "//":
            j = text.find("\n", i)
            j = n if j < 0 else j
            out.append(" " * (j - i))
            i = j
        elif two == "/*":
            j = text.find("*/", i + 2)
            j = n if j < 0 else j + 2
            out.append("".join(ch if ch == "\n" else " " for ch in text[i:j]))
            i = j
        elif c == '"' or (c in "@$" and text[i:i + 3].lstrip("@$").startswith('"')):
            k = i
            verbatim = False
            while text[k] in "@$":
                verbatim = verbatim or text[k] == "@"
                k += 1
            j = k + 1
            while j < n:
                if verbatim:
                    if text[j] == '"':
                        if text[j:j + 2] == '""':
                            j += 2
                            continue
                        break
                else:
                    if text[j] == "\\":
                        j += 2
                        continue
                    if text[j] == '"' or text[j] == "\n":
                        break
                j += 1
            j = min(j + 1, n)
            out.append('"' + "".join(ch if ch == "\n" else " " for ch in text[i + 1:j - 1]) + '"' if j - i >= 2 else text[i:j])
            i = j
        elif c == "'":
            j = i + 1
            while j < n and text[j] != "'" and text[j] != "\n":
                j += 2 if text[j] == "\\" else 1
            j = min(j + 1, n)
            out.append("' '".ljust(j - i)[:j - i] if j - i >= 3 else text[i:j])
            i = j
        elif c == "#" and text[:i].rstrip(" \t").endswith(("\n", "")) and (i == 0 or text[:i].rstrip(" \t")[-1:] in ("\n", "")):
            j = text.find("\n", i)
            j = n if j < 0 else j
            out.append(" " * (j - i))
            i = j
        else:
            out.append(c)
            i += 1
    return "".join(out)


def scan(path):
    text = blank_noise(read(path))
    types, methods = [], []
    stack = []
    stmt = []
    stmt_line = None
    line = 1
    paren = 0
    for ch in text:
        if ch == "\n":
            line += 1
            if stmt:
                stmt.append(" ")
            continue
        if ch == "(":
            paren += 1
        elif ch == ")":
            paren -= 1
        if ch in "{;}" and paren <= 0:
            paren = 0
            head = "".join(stmt).strip()
            start = stmt_line or line
            stmt = []
            stmt_line = None
            if ch == "{":
                kind, name = "block", None
                clean = ATTR_RX.sub("", head)
                in_type = bool(stack) and stack[-1][0] == "type"
                top = all(s[0] == "namespace" for s in stack)
                m = TYPE_RX.search(clean)
                ns = NAMESPACE_RX.search(clean)
                if m and (top or in_type) and "(" not in clean[:m.start()] and "=" not in clean[:m.start()]:
                    kind, name = "type", m.group(2)
                    types.append({"kind": m.group(1), "name": name, "start": start, "end": None, "depth": sum(1 for s in stack if s[0] == "type")})
                    stack.append((kind, len(types) - 1))
                    continue
                if ns and top:
                    stack.append(("namespace", None))
                    continue
                if in_type:
                    name = method_name(clean)
                    if name:
                        methods.append({"name": name, "line": start, "type": stack[-1][1]})
                stack.append((kind, None))
            elif ch == "}":
                if stack:
                    kind, idx = stack.pop()
                    if kind == "type":
                        types[idx]["end"] = line
            else:
                if stack and stack[-1][0] == "type" and "=>" in head:
                    name = method_name(ATTR_RX.sub("", head).split("=>")[0])
                    if name:
                        methods.append({"name": name, "line": start, "type": stack[-1][1]})
                if not stack:
                    ns = NAMESPACE_RX.match(head)
                    if ns:
                        pass
            continue
        if not stmt and ch in " \t":
            continue
        if not stmt:
            stmt_line = line
        stmt.append(ch)
    total = line
    for t in types:
        if t["end"] is None:
            t["end"] = total
    return types, methods, total


def method_name(head):
    head = head.strip()
    cut = head.find(" where ")
    if cut > 0:
        head = head[:cut].strip()
    cut = head.find(" : ")
    if cut > 0 and head[:cut].rstrip().endswith(")"):
        head = head[:cut].strip()
    if not head.endswith(")"):
        return None
    depth = 0
    for i in range(len(head) - 1, -1, -1):
        if head[i] == ")":
            depth += 1
        elif head[i] == "(":
            depth -= 1
            if depth == 0:
                before = head[:i + 1]
                break
    else:
        return None
    if "=" in before.replace("==", "").replace("<=", "").replace(">=", "").replace("!=", ""):
        return None
    m = METHOD_RX.search(before)
    if not m or m.group(1) in NOT_METHODS:
        return None
    if before[:m.start()].strip() == "" and not m.group(1)[0].isupper():
        return None
    return m.group(1)


def count_lines(path):
    text = read(path)
    return text.count("\n") + (0 if text.endswith("\n") or not text else 1)


def guid_of(meta_path):
    try:
        m = re.search(r"^guid:\s*([0-9a-f]{32})", read(meta_path), re.M)
    except OSError:
        return None
    return m.group(1) if m else None


def assemblies():
    by_guid, defs = {}, []
    for d, _, files in os.walk(os.path.join(ROOT, "Assets")):
        for f in files:
            if f.endswith(".asmdef"):
                p = rel(os.path.join(d, f))
                try:
                    data = json.loads(read(p))
                except ValueError:
                    continue
                g = guid_of(p + ".meta")
                if g:
                    by_guid[g] = data.get("name", f)
                if any(p.startswith(b + "/") for b in CODE_ROOTS):
                    defs.append((p, data))
    rows = []
    for p, data in sorted(defs):
        named, external = [], 0
        for r in data.get("references", []):
            if r.startswith("GUID:"):
                n = by_guid.get(r[5:])
                if n:
                    named.append(n)
                else:
                    external += 1
            else:
                named.append(r)
        rows.append((data.get("name", "?"), os.path.dirname(p), sorted(named), external))
    return rows


def build():
    files = cs_files()
    lines = {f: count_lines(f) for f in files}
    scans = {f: scan(f) for f in files if f not in SKIP_FILES}
    asm = assemblies()
    asm_dirs = sorted((d for _, d, _, _ in asm), key=len, reverse=True)

    idx = ["# Code index", "",
           "Generated by `tools/docmap.py`. Do not edit by hand; run `python3 tools/docmap.py gen`.",
           "Use it by search: `grep -n \"TypeName\" docs/map/INDEX.md`.", ""]

    idx += ["## Folders", "", "Files and lines of `.cs` directly in the folder.", "", "| Folder | Files | Lines |", "|---|---|---|"]
    per_dir = {}
    for f in files:
        d = os.path.dirname(f)
        a = per_dir.setdefault(d, [0, 0])
        a[0] += 1
        a[1] += lines[f]
    for d in sorted(per_dir):
        idx.append("| `%s` | %d | %d |" % (d, per_dir[d][0], per_dir[d][1]))
    idx.append("")

    idx += ["## Assemblies", "", "References are resolved from GUIDs; `+N` is the number of package assemblies outside `Assets/`.", "",
            "| Assembly | Root | References |", "|---|---|---|"]
    for name, d, named, external in asm:
        refs = ", ".join(named) + (" +%d" % external if external else "")
        idx.append("| %s | `%s` | %s |" % (name, d, refs or "—"))
    idx.append("")
    loose = sorted({os.path.dirname(f) for f in files
                    if f.startswith("Assets/Scripts/") and not any(f.startswith(a + "/") for a in asm_dirs)})
    tops = sorted({"/".join(d.split("/")[:3]) for d in loose})
    idx += ["Folders compiled into `Assembly-CSharp` (no asmdef above them): " + ", ".join("`%s`" % t for t in tops) + ".", ""]

    idx += ["## Types declared in a file with another name", "",
            "Top-level types only. A type missing here lives in `<TypeName>.cs`.", "", "| Type | Kind | File | Line |", "|---|---|---|---|"]
    rows = []
    for f, (types, _, _) in scans.items():
        base = os.path.basename(f)[:-3].split(".")[0]
        for t in types:
            if t["depth"] == 0 and t["name"] != base:
                rows.append((t["name"], t["kind"], f, t["start"]))
    for r in sorted(rows, key=lambda r: (r[0].lower(), r[2])):
        idx.append("| %s | %s | `%s` | %d |" % r)
    idx.append("")

    idx += ["## Files not to read", "", "| File | Lines | Why |", "|---|---|---|"]
    for f, why in sorted(SKIP_FILES.items()):
        if f in lines:
            idx.append("| `%s` | %d | %s |" % (f, lines[f], why))
    idx.append("")

    big = ["# Large files", "",
           "Generated by `tools/docmap.py`. Do not edit by hand; run `python3 tools/docmap.py gen`.",
           "Own files over %d lines. Find the member here, then read only its line range." % LARGE_LIMIT,
           "Line numbers are those of the last generation; after local edits treat them as approximate.", ""]
    large = sorted((f for f in scans if lines[f] > LARGE_LIMIT), key=lambda f: -lines[f])
    big += ["| File | Lines |", "|---|---|"]
    for f in large:
        big.append("| `%s` | %d |" % (f, lines[f]))
    big.append("")
    for f in large:
        types, methods, _ = scans[f]
        big += ["## `%s`" % f, ""]
        for i, t in enumerate(types):
            pad = "  " * t["depth"]
            big.append("%s- %d–%d %s %s" % (pad, t["start"], t["end"], t["kind"], t["name"]))
            own = [m for m in methods if m["type"] == i]
            for m in own:
                big.append("%s  - %d %s" % (pad, m["line"], m["name"]))
        big.append("")
    return "\n".join(idx) + "\n", "\n".join(big) + "\n"


def write(path, text):
    full = os.path.join(ROOT, path)
    os.makedirs(os.path.dirname(full), exist_ok=True)
    with open(full, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)


def doc_files():
    out = [d for d in CHECKED_DOCS + SCRIPT_RELATIVE_DOCS if os.path.exists(os.path.join(ROOT, d))]
    for base in CHECKED_DIRS:
        for d, _, files in os.walk(os.path.join(ROOT, base)):
            out += [rel(os.path.join(d, f)) for f in files if f.endswith(".md")]
    for base in CODE_ROOTS:
        for d, _, files in os.walk(os.path.join(ROOT, base)):
            out += [rel(os.path.join(d, f)) for f in files if f in ("CLAUDE.md", "AGENTS.md")]
    return sorted(set(out))


def looks_like_path(token):
    if any(c in token for c in " *<>{}|()=,;:\"'`$\\") or token.startswith(("http", "~", "-", "/", ".")):
        return False
    if "…" in token or "..." in token:
        return False
    if token.endswith("/"):
        return True
    return "/" in token and token.endswith(PATH_EXT)


def check_paths():
    bad = []
    generated = {INDEX_PATH, LARGE_PATH}
    basenames = set()
    for d, dirs, files in os.walk(ROOT):
        dirs[:] = [x for x in dirs if x not in (".git", "Library", "Temp", "Logs", "obj")]
        basenames.update(files)
    for doc in doc_files():
        if doc in generated:
            continue
        text = read(doc)
        bases = [""]
        here = os.path.dirname(doc)
        if doc in SCRIPT_RELATIVE_DOCS:
            bases += ["Assets/Scripts", "Assets"]
        for n, line in enumerate(text.split("\n"), 1):
            cands = [(t, bases) for t in re.findall(r"`([^`\n]+)`", line) if looks_like_path(t)]
            for target in re.findall(r"\]\(([^)#\s]+)(?:#[^)]*)?\)", line):
                if not target.startswith(("http", "mailto")):
                    cands.append((target, [here]))
            for t in re.findall(r"`([^`\n/ ]+)`", line):
                if t.endswith(PATH_EXT) and not t.startswith(".") and "*" not in t and "<" not in t and t not in basenames:
                    bad.append("%s:%d: %s" % (doc, n, t))
            for token, bs in cands:
                if not any(os.path.exists(os.path.join(ROOT, b, token.rstrip("/"))) for b in bs):
                    bad.append("%s:%d: %s" % (doc, n, token))
    return bad


IDENT_RX = re.compile(r"^[A-Za-z_]\w*(\.[A-Za-z_]\w*)*(\(\))?$")
WORD_RX = re.compile(r"[A-Za-z_]\w*")
IDENT_SOURCES = (".cs", ".hlsl", ".shader", ".compute", ".asmdef", ".inputactions")
IDENT_DIRS = ["Assets/Scripts", "Assets/Tests", "Assets/Shaders"]
IDENT_DOCS_SKIP = {INDEX_PATH, LARGE_PATH, "docs/OPTIMIZATION.md", "docs/SECURITY.md", "docs/PROMPT_TEMPLATE.md"}
IDENT_ALLOW = {"main", "grep", "git", "mv", "python3", "gen", "check", "strict", "meta", "asmdef", "md", "cs", "ignore",
               "UPM", "CLAUDE", "AGENTS", "README", "TODO", "N", "K", "M"}


def known_words():
    words = set()
    for base in IDENT_DIRS:
        for d, _, files in os.walk(os.path.join(ROOT, base)):
            for f in files:
                if f.endswith(IDENT_SOURCES):
                    words.update(WORD_RX.findall(read(rel(os.path.join(d, f)))))
                words.update(WORD_RX.findall(f))
            words.update(WORD_RX.findall(os.path.basename(d)))
    return words


def check_identifiers():
    words = known_words()
    bad = []
    for doc in doc_files():
        if doc in IDENT_DOCS_SKIP:
            continue
        fenced = False
        for n, line in enumerate(read(doc).split("\n"), 1):
            if line.lstrip().startswith("```"):
                fenced = not fenced
                continue
            if fenced:
                continue
            for token in re.findall(r"`([^`\n]+)`", line):
                if not IDENT_RX.match(token) or looks_like_path(token) or token.endswith(PATH_EXT):
                    continue
                parts = [w for w in WORD_RX.findall(token) if w not in IDENT_ALLOW]
                missing = [w for w in parts if w not in words]
                if missing:
                    bad.append("%s:%d: %s" % (doc, n, token))
    return bad


def main():
    cmd = sys.argv[1] if len(sys.argv) > 1 else ""
    if cmd == "gen":
        index, large = build()
        write(INDEX_PATH, index)
        write(LARGE_PATH, large)
        print("written %s, %s" % (INDEX_PATH, LARGE_PATH))
        return 0
    if cmd == "check":
        strict = "--strict" in sys.argv
        code = 0
        bad = check_paths()
        for b in bad:
            print("missing path  " + b)
        if bad:
            code = 1
        unknown = check_identifiers()
        for u in unknown:
            print("unknown name  " + u)
        if unknown:
            code = 1
        index, large = build()
        for path, text in ((INDEX_PATH, index), (LARGE_PATH, large)):
            full = os.path.join(ROOT, path)
            current = open(full, encoding="utf-8").read() if os.path.exists(full) else ""
            if current != text:
                print("stale         %s (run: python3 tools/docmap.py gen)" % path)
                if strict:
                    code = 1
        if code == 0:
            print("docs ok")
        return code
    print("usage: docmap.py gen | check [--strict]")
    return 2


if __name__ == "__main__":
    sys.exit(main())
